import React from 'react';

import clsx from 'clsx';
import * as L from 'leaflet';
import { createRoot } from 'react-dom/client';
import 'leaflet/dist/leaflet.css';
import { useNavigate } from 'react-router-dom';

import { getHikingAccessGroupAsync } from '@apps/Hiking/@services/hikingRules.service';
import { HikingAccessGroup } from '@apps/Hiking/@types/hiking.rules';
import { watermarkToMap } from '@apps/Routes/@helpers/addToMap.helper';
import { setMarkerSimpleIcon, setPolylineStyles } from '@apps/Routes/@helpers/routeObjects.helper';
import { mapRouteObjectToPolylineStyle } from '@apps/Routes/@helpers/routeObjectStyles.helper';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import { stringToColour } from '@helpers/colorsizeStringHelper';
import { getMap, quadkey } from '@helpers/leafletHelper';
import { success } from '@helpers/notificationHelper';
import PohAlert from '@ui-kit/Alert';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonSize, ButtonVariant } from '@ui-kit/Button';
import IconsEnum from '@ui-kit/Icon/IconsEnum';
import PohCol from '@ui-kit/layout/Col';
import PohContainer from '@ui-kit/layout/Container';
import PohRow from '@ui-kit/layout/Row';
import PohList from '@ui-kit/List';
import { confirmModal2 } from '@ui-kit/Modal/modalsHelper';

import { selectWorkoutInModalAsync } from './components/addHikingTrackHelper';
import HikingTrackListItem from './components/HikingTrackListItem';
import style from './styel.module.less';
import { getObstacleTitle } from '../../../Obstacles/@helpers/obstacles.helper';
import { setMarkerObstacle } from '../../../Routes/@helpers/leaflet.helper';
import {
  getBaseRouteDataAsync,
  getRouteObjectsAsync,
  IBaseRouteData,
} from '../../../Routes/@services/routes.service';
import { IRouteObject, RouteObjectType } from '../../../Routes/@types/routes.types';
import { getHikingDataAsync } from '../../@services/hiking.service';
import { addHikingGpx, delHikingGpx, getHikingGpx } from '../../@services/hikingResults.service';
import { IHikingData, IHikingGpx } from '../../@types/hiking.types';

const startIcon = L.divIcon({
  className: clsx(style.icon, style.iconStart),
  html: '1',
  iconSize: [16, 16],
  iconAnchor: [16, 16],
});
const endIcon = L.divIcon({
  className: clsx(style.icon, style.iconEnd),
  html: '2',
  iconSize: [16, 16],
  iconAnchor: [16, 16],
});

const planLineBg = 'lime';
const planLineOpacity = 0.8;

interface IHikingTracksProps {
  id_hiking: number;
}

const HikingTracks: React.FC<IHikingTracksProps> = ({ id_hiking }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [canEdit, setCanEdit] = React.useState(false);
  const [tracks, setTracks] = React.useState<IHikingGpx[]>([]);

  const [routeData, setRouteData] = React.useState<IBaseRouteData | null>(null);
  const [routeObjectsData, setRouteObjectsData] = React.useState<IRouteObject[]>([]);
  const [err, setErr] = React.useState<Error>();
  const [isLoading, setIsLoading] = React.useState(false);

  const navigate = useNavigate();

  const fetchData = React.useCallback(async () => {
    try {
      setIsLoading(true);

      const hikingDataRes = await getHikingDataAsync(id_hiking);
      setHikingData(hikingDataRes);

      const accessGroup = await getHikingAccessGroupAsync(id_hiking);
      setCanEdit(
        [
          HikingAccessGroup.Full,
          HikingAccessGroup.All,
          HikingAccessGroup.Boss,
          HikingAccessGroup.Routes,
        ].includes(accessGroup),
      );

      const tracksRes = await getHikingGpx(id_hiking);
      setTracks(tracksRes);

      if (hikingDataRes.route?.id) {
        const routeObjectsRes = await getRouteObjectsAsync(hikingDataRes.route.id);
        setRouteObjectsData(routeObjectsRes);

        const brd = await getBaseRouteDataAsync(hikingDataRes.route.id);
        setRouteData(brd);
      }
    } catch (e) {
      setErr(e as Error);
      console.error(e);
    } finally {
      setIsLoading(false);
    }
  }, [id_hiking]);

  React.useEffect(() => {
    fetchData();
  }, [fetchData]);

  const mapContainerRef = React.useRef<HTMLDivElement>(null);
  const mapRef = React.useRef<L.Map>(null);

  React.useEffect(() => {
    if (
      mapRef.current ||
      !tracks ||
      !mapContainerRef.current ||
      !routeData?.routeData ||
      !routeObjectsData
    ) {
      return;
    }
    const map = getMap(mapContainerRef.current, {
      fullscreenControl: true,
    });

    const legend = new L.Control({ position: 'topright' });

    legend.onAdd = function () {
      const div = L.DomUtil.create('div');
      const root = createRoot(div);

      root.render(
        <div className="bg-light px-2">
          <span style={{ color: planLineBg, opacity: planLineOpacity }}>▬</span> План
        </div>,
      );

      return div;
    };
    legend.addTo(map);

    L.tileLayer(
      routeData.typeData.tileUrlTmpl,
      L.Util.extend({ quadkey }, routeData.typeData.name),
    ).addTo(map);
    watermarkToMap(map);

    const routeObjectsFeatureGroup = new L.FeatureGroup();
    const tracksFeatureGroup = new L.FeatureGroup();
    routeObjectsFeatureGroup.addTo(map);
    tracksFeatureGroup.addTo(map);

    routeObjectsData.forEach((a) => {
      if (a.type === RouteObjectType.Point) {
        const pl = L.marker(a.coordinates);
        setMarkerSimpleIcon(pl, a.color);
        a.obstacle && setMarkerObstacle(pl, a.obstacle, a.is_in_distance);

        if (a.name.length) {
          pl.bindTooltip(`${a.name}\n${a.obstacle ? getObstacleTitle(a.obstacle) : ''}`);
        }
        if (a.description.length) {
          pl.bindPopup(a.description);
        }
        pl.addTo(routeObjectsFeatureGroup);
      } else if (a.type === RouteObjectType.Line) {
        const pl = new L.Polyline(a.points);
        setPolylineStyles(pl, {
          ...mapRouteObjectToPolylineStyle(a),
          color: planLineBg,
          opacity: planLineOpacity,
          weight: 3,
        } as L.PolylineOptions);
        pl.addTo(routeObjectsFeatureGroup);
      }
    });

    tracks.forEach((track) => {
      const trackCoordinates = track.track.map((tp) => tp.point);
      const pl = new L.Polyline(trackCoordinates, { color: stringToColour(track.name) });
      pl.addTo(tracksFeatureGroup);

      new L.Marker(trackCoordinates[0], {
        icon: startIcon,
      }).addTo(tracksFeatureGroup);
      new L.Marker(trackCoordinates[trackCoordinates.length - 1], {
        icon: endIcon,
      }).addTo(tracksFeatureGroup);
    });

    const bounds = tracksFeatureGroup.getBounds();
    if (bounds.isValid()) map.fitBounds(bounds);

    mapRef.current = map;
  }, [mapContainerRef.current, routeData, routeObjectsData, tracks]);

  if (err) {
    return <PohAlert>{err.message}</PohAlert>;
  }
  if (isLoading) {
    return <PageLoader />;
  }

  if (!hikingData) return <PohAlert>wrong hikingData</PohAlert>;

  const handleClick = (track: IHikingGpx) => () => {
    mapRef.current?.flyToBounds(track.bounds);
  };

  const handleAdd = () => {
    selectWorkoutInModalAsync({ d1: hikingData.start, d2: hikingData.finish }).then(
      (selectedWorkout) => {
        addHikingGpx(id_hiking, selectedWorkout.id_workout_track, selectedWorkout.name).then(
          (ss) => {
            success(ss.msg);
            fetchData();
          },
        );
      },
    );
  };
  const handleDel = async (id: number) => {
    const ok = await confirmModal2(`Удалить трек из похода?`);
    if (!ok) return;
    delHikingGpx({ id_hiking: hikingData.id, id }).then(() => {
      success('Удалено!');
      fetchData();
    });
  };

  return (
    <>
      <Breadcrumb
        data={[
          { href: '/hiking', text: 'Походы' },
          { href: `/hiking/${id_hiking}`, text: hikingData.name },
          { href: `/hiking/${id_hiking}/tracks`, text: 'GPS Треки', active: true },
        ]}
      />
      <PohContainer>
        <PageHeader title={`GPS Треки похода «${hikingData.name}»`}>&nbsp;</PageHeader>
        <PohRow>
          <PohCol sm={7}>
            Карта
            <div ref={mapContainerRef} style={{ height: 600 }} />
          </PohCol>
          <PohCol sm={5}>
            <header className="d-flex align-items-center border-bottom mb-2 pb-2">
              <h5 className="m-0">Треки</h5>
              <aside className="ms-auto">
                {canEdit && (
                  <PohButton
                    variant={ButtonVariant.Success}
                    onClick={handleAdd}
                    size={ButtonSize.Small}
                  >
                    Добавить трек
                  </PohButton>
                )}
              </aside>
            </header>
            <PohList
              flush
              data={tracks.map((track) => ({
                key: track.id,
                action: true,
                content: (
                  <HikingTrackListItem
                    hikingGpxTrack={track}
                    toolbar={
                      <>
                        {canEdit && (
                          <>
                            <PohButton
                              icon={IconsEnum.edit}
                              size={ButtonSize.Small}
                              onClick={() => navigate(`/hiking/${id_hiking}/tracks/${track.id}`)}
                            />
                            <PohButton
                              size={ButtonSize.Small}
                              icon={IconsEnum.trash}
                              onClick={() => handleDel(track.id)}
                            />
                          </>
                        )}
                      </>
                    }
                  />
                ),
                onClick: handleClick(track),

                style: { borderLeft: `3px solid ${stringToColour(track.name)}` },
              }))}
            />
          </PohCol>
        </PohRow>
      </PohContainer>
    </>
  );
};

export default HikingTracks;
